const DB_NAME='talentisos', STORE='state';
const seed={tasks:[{id:'t1',title:'Confirm service priorities with the team',status:'open',priority:'high',due:today(),carry:1,source:'EOD'},{id:'t2',title:'Review weekly customer response time',status:'open',priority:'medium',due:today(),carry:0,source:'Huddle'},{id:'t3',title:'Prepare consumables stock-out update',status:'open',priority:'high',due:tomorrow(),carry:0,source:'Today'}],eod:{completed:'Closed out priority customer follow-ups',outstanding:'',risks:'',top3:'Confirm service priorities with the team\nReview weekly customer response time\nPrepare consumables stock-out update',handovers:''},kpis:[{id:'k1',category:'Customer care',name:'Orders completed',purpose:'Weekly orders completed',owner:'Customer care',target:8,warning:6,red:4,unit:'/ week',direction:'higher',actual:8,history:[]},{id:'k2',category:'Help desk',name:'Resolution percentage',purpose:'Issues resolved within service standard',owner:'Help desk',target:35,warning:30,red:20,unit:'%',direction:'higher',actual:32,history:[]},{id:'k3',category:'Consumables',name:'Stock-out orders',purpose:'Orders affected by stock-outs',owner:'Consumables',target:0,warning:2,red:4,unit:' this week',direction:'lower',actual:2,history:[]},{id:'k4',category:'Service control',name:'Response time',purpose:'Average customer response time',owner:'Service control',target:3,warning:4,red:5,unit:' hrs',direction:'lower',actual:4.2,history:[]}],issues:[],l10:{section:'Segue',running:false},settings:{},eodHistory:[]};
let state, current='dashboard', taskSortMode='priority', taskGroupMode='priority', todayPriorityFilter='all', todaySearch='';
const DEFAULT_SYNC_API='';
function syncApi(){return String(state?.settings?.syncApi||localStorage.getItem('talentisos-sync-url')||DEFAULT_SYNC_API).replace(/\/$/,'')}
async function cloudLoad(){const base=syncApi();if(!base)return null;try{const response=await fetch(`${base}/api/data`,{credentials:'include'});if(!response.ok)return null;const body=await response.json();return body.data?normalizeState(body.data):null}catch{return null}}
async function cloudSave(snapshot){const base=syncApi();if(!base)return;try{await fetch(`${base}/api/data`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)})}catch{}}

const navItems=[['today','&#10003;','Today'],['meetings','&#9673;','Meetings'],['insights','&#9672;','Insights'],['settings','&#9881;','Settings']];
function navActive(id){if(id==='today')return ['today','dashboard','tasks','huddle','eod'].includes(current);if(id==='meetings')return ['meetings','l10','rocks','ids'].includes(current);if(id==='insights')return ['insights','performance','scorecard','management-kpis'].includes(current);return current===id}
function today(){return new Date().toISOString().slice(0,10)} function tomorrow(){const d=new Date();d.setDate(d.getDate()+1);return d.toISOString().slice(0,10)}
function fridayOfWeek(value=today()){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+(5-d.getDay()));return d.toISOString().slice(0,10)}
function addWeeks(value,weeks){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+weeks*7);return d.toISOString().slice(0,10)}
function openDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('IndexedDB unavailable'));const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('IndexedDB unavailable'));r.onblocked=()=>reject(new Error('IndexedDB blocked'))})}
function cloneData(value){return typeof structuredClone==='function'?structuredClone(value):JSON.parse(JSON.stringify(value))}
function normalizeState(input){const base=cloneData(seed),source=input&&typeof input==='object'?input:{},normal={...base,...source,eod:{...base.eod,...(source.eod||{})},settings:{...base.settings,...(source.settings||{})},tasks:Array.isArray(source.tasks)?source.tasks:base.tasks,issues:Array.isArray(source.issues)?source.issues:base.issues,l10:{...base.l10,...(source.l10||{})}};normal.kpis=(Array.isArray(source.kpis)?source.kpis:base.kpis).map((k,i)=>{if(Array.isArray(k)){const raw=String(k[2]||''),actual=parseFloat(raw),lower=k[0]==='Consumables'||k[1]==='Response time';return {id:'k'+(i+1),category:k[0]||'General',name:k[1]||'Untitled KPI',purpose:'Operational performance measure',owner:k[0]||'Team focus',target:lower?0:actual||0,warning:lower?actual||1:(actual||0)*.85,red:lower?(actual||1)*2:(actual||0)*.7,unit:raw.replace(/[\d.\s]/g,'')||'',direction:lower?'lower':'higher',actual:Number.isNaN(actual)?'':actual,history:[]}}return {...k,id:k.id||'k'+(i+1),category:k.category||'General',name:k.name||'Untitled KPI',history:Array.isArray(k.history)?k.history.filter(h=>h&&h.date):[]}});return normal}
async function load(){try{const db=await openDB();const stored=await new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get('app');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const local=normalizeState(stored||cloneData(seed));return (await cloudLoad())||local}catch{try{return normalizeState(JSON.parse(localStorage.getItem(DB_NAME)||'null')||cloneData(seed))}catch{return normalizeState(null)}}}
async function save(){const snapshot=cloneData(state);try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(snapshot,'app');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Save aborted'))})}catch{try{localStorage.setItem(DB_NAME,JSON.stringify(snapshot))}catch{toast('Could not save locally')}}void cloudSave(snapshot)}
function emptyWorkspace(){return {...cloneData(seed),tasks:[],kpis:[],issues:[],eod:{completed:'',outstanding:'',risks:'',top3:'',handovers:''},l10:{section:'Segue',running:false},settings:{},eodHistory:[]}}
function esc(s=''){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function closestFromEvent(event,selector){const target=event?.target;return target instanceof Element?target.closest(selector):null}
function fmt(d){return d?new Date(d+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'}):'No due date'}
function kpiStatusForValue(k,value){if(value===''||value==null||Number.isNaN(Number(value)))return'not-reported';const v=Number(value);return k.direction==='lower'?(v<=Number(k.target)?'on-track':v<=Number(k.warning)?'at-risk':'off-track'):(v>=Number(k.target)?'on-track':v>=Number(k.warning)?'at-risk':'off-track')}
function kpiStatus(k){return kpiStatusForValue(k,k.actual)}
function kpiDisplay(k,value=k.actual){return value===''||value==null?'&#8212;':`${value}${k.unit||''}`}
function latestKpiDate(k){return [...(k.history||[]).map(h=>h.date)].sort().at(-1)||fridayOfWeek()}
function layout(){document.querySelector('#nav').innerHTML=navItems.map(([id,icon,label])=>`<button class="${navActive(id)?'active':''}" aria-current="${navActive(id)?'page':'false'}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');document.querySelector('#breadcrumb')?.remove();document.querySelector('#today-date')?.remove();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='settings'){settingsDialog();return}current=b.dataset.view;document.querySelector('.sidebar').classList.remove('open');render()})}
function taskRow(t){return `<div class="task-row"><button class="check ${t.status==='done'?'done':''}" data-complete="${esc(t.id)}" aria-label="Complete task">${t.status==='done'?'&#10003;':''}</button><div class="task-copy"><strong class="${t.status==='done'?'muted':''}">${esc(t.title)}</strong><small>${esc(t.source||'Task')}${t.carry?' &#183; carried '+esc(t.carry)+'&#215;':''}</small></div><span class="task-due ${t.due<today()&&t.status!=='done'?'overdue':''}">${fmt(t.due)}</span><div class="task-actions"><button class="button small" data-edit-task="${esc(t.id)}">Edit</button><button class="button small delete-link" data-delete-task="${esc(t.id)}">Delete</button></div></div>`}
function metricDetails(kind){const open=state.tasks.filter(t=>t.status!=='done'),top3=state.eod.top3.split('\n').filter(Boolean);if(kind==='commitments')return `<div class="detail-heading"><div><div class="section-kicker">OPEN COMMITMENTS</div><h3>What is still in motion</h3></div><button class="button small" data-view="tasks">View tasks &#8594;</button></div><div class="detail-grid"><div>${open.slice(0,4).map(taskRow).join('')||'<div class="empty">No open commitments.</div>'}</div><div class="detail-aside"><strong>${open.filter(t=>t.due===today()).length} due today</strong><span>Keep the day narrow and finish what matters most.</span></div></div>`;if(kind==='top3')return `<div class="detail-heading"><div><div class="section-kicker">TOP 3 READY</div><h3>Tomorrow already has a shape</h3></div><button class="button small" data-view="huddle">Open huddle &#8594;</button></div><div class="detail-grid"><div>${top3.map((item,i)=>`<div class="detail-list-row"><b>0${i+1}</b><span>${esc(item)}</span></div>`).join('')||'<div class="empty">Prepare your Top 3 in End of Day.</div>'}</div><div class="detail-aside"><strong>Aligned from EOD</strong><span>Carry forward the decisions and priorities without re-entering them.</span></div></div>`;if(kind==='kpis')return `<div class="detail-heading"><div><div class="section-kicker">KPI EXCEPTIONS</div><h3>Signals that need a response</h3></div><button class="button small" data-view="scorecard">Open scorecard &#8594;</button></div><div class="detail-grid"><div>${state.kpis.filter(k=>kpiStatus(k)!=='on-track').map(k=>{const status=kpiStatus(k);return`<div class="detail-list-row"><span class="kpi-status ${status}"></span><span><strong>${esc(k.name)}</strong><small>${esc(k.category)} &#183; actual ${esc(kpiDisplay(k))} &#183; target ${esc(kpiDisplay(k,k.target))}</small></span><em class="status ${status}">${status==='at-risk'?'At risk':'Off track'}</em></div>`}).join('')||'<div class="empty">No exceptions right now.</div>'}</div><div class="detail-aside"><strong>Amber + red</strong><span>Each exception should have a corrective action linked in IDS.</span></div></div>`;return `<div class="detail-heading"><div><div class="section-kicker">LEADERSHIP RHYTHM</div><h3>Prepare &#8594; Align &#8594; Execute &#8594; Review &#8594; Improve</h3></div><button class="button small" data-view="huddle">Continue rhythm &#8594;</button></div><div class="rhythm-steps"><div class="rhythm-step complete"><b>01</b><span>Prepare</span><small>Complete</small></div><div class="rhythm-step complete"><b>02</b><span>Align</span><small>Complete</small></div><div class="rhythm-step active"><b>03</b><span>Execute</span><small>Today</small></div><div class="rhythm-step"><b>04</b><span>Review</span><small>Next</small></div><div class="rhythm-step"><b>05</b><span>Improve</span><small>Next</small></div></div>`}
function rhythmScore(){return [state.eod.completed,state.eod.top3,state.tasks.some(t=>t.status==='done'),state.kpis.some(k=>k.history?.length),state.issues.length].filter(Boolean).length}
function meetingHealth(){return Math.max(0,Math.min(10,Number(state.l10?.rating)||0))}
function dashboard(){const open=state.tasks.filter(t=>t.status!=='done'),top3=state.eod.top3.split('\n').filter(Boolean);return `<div class="dashboard-hero"><div class="dashboard-intro"><div class="kicker">TALENTISOS &#183; TODAY</div><h1>Lead the day<br>before it leads you.</h1><p>Your calm daily operating rhythm for priorities, risks, commitments and progress.</p></div><div class="dashboard-actions"><button class="action-tile action-primary" data-view="eod"><span>&#65291;</span><strong>Quick close</strong><small>End of Day</small></button><button class="action-tile" data-view="today"><span>&#8594;</span><strong>Today&#8217;s work</strong><small>Open commitments</small></button></div></div><div class="metric-strip"><button class="metric-item" data-metric="commitments" aria-expanded="false"><span>Open commitments</span><strong>${open.length}</strong><small>${open.filter(t=>t.due===today()).length} due today</small></button><button class="metric-item" data-metric="top3" aria-expanded="false"><span>Top 3 ready</span><strong>${top3.length}</strong><small>Aligned from your EOD</small></button><button class="metric-item" data-metric="kpis" aria-expanded="false"><span>KPI exceptions</span><strong>${state.kpis.filter(k=>kpiStatus(k)!=='on-track').length}</strong><small>Need attention this week</small></button><button class="metric-item" data-metric="rhythm" aria-expanded="false"><span>Rhythm this week</span><strong>${rhythmScore()}<span>/5</span></strong><small>Prepare &#8594; Improve</small></button></div><div id="metric-detail" class="metric-detail" hidden></div><div class="feature-strip"><div class="feature-lead"><div class="kicker">AVAILABLE TODAY</div><div class="feature-number">${open.length ? open[0].title : 'No open commitments'}</div><p>Start with the commitment that most improves the day. Tap to open your execution workspace.</p><button class="button teal" data-view="today">Open Today&#8217;s Work &#8594;</button></div><div class="feature-item"><span>Tomorrow&#8217;s Top 3</span><strong>${esc(top3[0]||'Prepare your priorities')}</strong><small>Prepared in End of Day</small></div><div class="feature-item"><span>Scorecard pulse</span><strong>${state.kpis.filter(k=>kpiStatus(k)!=='on-track').length} exceptions</strong><small>One amber, one red signal</small><button class="text-link" data-view="scorecard">Review scorecard &#8594;</button></div><div class="feature-item"><span>Leadership rhythm</span><strong>${rhythmScore()} days complete</strong><small>Keep the operating cadence moving</small><button class="text-link" data-view="huddle">Start huddle &#8594;</button></div></div><div class="dashboard-lower"><div><div class="section-kicker">YOUR FOCUS</div><h2 class="dashboard-section-title">What needs your attention</h2><div class="task-list">${open.slice(0,4).map(taskRow).join('')||'<div class="empty">Your commitments are clear. Nice work.</div>'}</div></div><div class="dashboard-note"><div class="section-kicker">CAPTURE ONCE &#183; CARRY FORWARD</div><h2 class="dashboard-section-title">Make the next handover easier.</h2><p>Close the loop now so tomorrow starts with clarity, not catch-up.</p><button class="button" data-add-task>&#65291; Add a commitment</button></div></div>`}
function updateEodChecklist(){document.querySelectorAll('[data-checklist-key]').forEach(item=>{const key=item.dataset.checklistKey,field=key==='top3'?document.querySelector('#top3'):document.querySelector('[name=\"'+key+'\"]'),hasText=String(field?.value||'').trim();item.classList.toggle('muted',Boolean(hasText));item.innerHTML=hasText?'&#10003;':'&#9675;'})}
document.addEventListener('input',event=>{if(event.target.matches('#eod-form textarea,#top3'))updateEodChecklist()},true);
function eod(){const checklist=['completed','outstanding','risks','top3'];return `<div class="hero"><div><div class="kicker">REVIEW &#8594; IMPROVE</div><h1>End of Day</h1><p>Close the loop while the day is still fresh. Capture once and carry forward what matters.</p></div><button class="button teal" data-save-eod>Save today&#8217;s close</button></div><div class="bento"><div class="card span-7"><h2 class="section-title">Daily close</h2><form class="form" id="eod-form"><label>What did you complete?<textarea class="textarea" name="completed">${esc(state.eod.completed)}</textarea></label><label>What remains outstanding?<textarea class="textarea" name="outstanding">${esc(state.eod.outstanding)}</textarea></label><label>Risks, customer issues or blockers<textarea class="textarea" name="risks">${esc(state.eod.risks)}</textarea></label><label>Handovers / notes<textarea class="textarea" name="handovers">${esc(state.eod.handovers)}</textarea></label></form></div><div class="card span-5"><h2 class="section-title">Tomorrow&#8217;s Top 3</h2><p class="muted">These priorities are ready for your morning huddle.</p><textarea class="textarea" id="top3">${esc(state.eod.top3)}</textarea><div class="card-head" style="margin-top:22px"><span class="card-label">Capture checklist</span><span class="status on-track">${String(state.eod.completed||'').trim()?'Ready':'In progress'}</span></div>${['Completed work','Outstanding work','Risks surfaced','Top 3 prepared'].map((x,i)=>{const value=String(state.eod?.[checklist[i]]||'').trim();return `<div class="status-row"><span>${x}</span><span data-checklist-key="${checklist[i]}" class="${value?'muted':''}">${value?'&#10003;':'&#9675;'}</span></div>`}).join('')}</div></div>${eodHistoryTimeline()}`}
function huddle(){const carry=state.tasks.filter(t=>t.status!=='done'&&t.movedToHuddleDate&&t.eodCategory!=='top-3'&&!t.title.startsWith('Top 3:')),top3=state.tasks.filter(t=>t.status!=='done'&&t.movedToHuddleDate&&(t.eodCategory==='top-3'||t.title.startsWith('Top 3:')));return '<div class="hero"><div><div class="kicker">PREPARE &#8594; ALIGN</div><h1>Morning Huddle</h1><p>Import outstanding work, risks, handovers and today&#8217;s Top 3 into one dated checklist.</p></div><div class="huddle-actions"><button class="button" data-import-eod>Import from End of Day</button></div></div><div class="bento"><div class="card span-8 huddle-carry-card"><div class="card-head"><h2 class="section-title">Carry-over checklist</h2><span class="pill">'+carry.length+' items</span></div><div class="task-list">'+(carry.map(taskRow).join('')||'<div class="empty">No EOD items have been imported yet.</div>')+'</div></div><div class="card span-4 huddle-prompts-card"><h2 class="section-title">Huddle prompts</h2><div class="status-row"><strong>Top 3</strong><span class="muted">What must be true by end of day?</span></div><div class="status-row"><strong>Risks</strong><span class="muted">Where do we need support?</span></div><div class="status-row"><strong>Commitments</strong><span class="muted">What will we own and communicate?</span></div></div><div class="card span-12"><div class="card-head"><h2 class="section-title">Today&#8217;s Top 3 from EOD</h2><span class="pill">'+top3.length+' items</span></div><div class="task-list">'+(top3.map(taskRow).join('')||'<div class="empty">Tap Import from End of Day to bring in today&#8217;s Top 3.</div>')+'</div></div></div>'}

function scoreCell(k,i,date){const entry=date?k.history?.find(h=>h.date===date):k.history?.[i],value=entry?.actual??(!k.history?.length&&i===0?k.actual:'');const status=kpiStatusForValue(k,value),tone=status==='on-track'?'good':status==='at-risk'?'amber':status==='off-track'?'bad':'neutral';if(value==='')return `<div class="matrix-cell ${tone}" title="${esc(k.name)} &#183; ${esc(kpiDisplay(k,value))}">${esc(kpiDisplay(k,value))}</div>`;return `<button type="button" class="matrix-cell ${tone} weekly-cell" data-weekly-cell="${esc(k.id)}|${esc(date)}" title="Edit ${esc(k.name)} ${esc(fmt(date))}">${esc(kpiDisplay(k,value))}</button>`}
function weeklyActualModal(k,date){const entry=k.history?.find(h=>h.date===date),current=entry?.actual??(!k.history?.length?k.actual:null);if(current==null||current==='')return;modal('Edit weekly actual',`<div class="form"><label>KPI<input class="input" value="${esc(k.name)}" readonly/></label><label>Week ending<input class="input" value="${esc(fmt(date))}" readonly/></label><label>Actual achieved<input class="input actual-edit-input" name="actual" type="number" step="any" value="${esc(current)}" autofocus/></label><p class="muted form-hint">This changes only the selected week. The Scorecard colour will recalculate automatically.</p><button type="button" class="button delete-link" data-delete-weekly="${esc(k.id)}|${esc(date)}">Delete this actual</button></div>`,m=>{const raw=m.querySelector('[name=actual]').value;if(raw==='')return;const actual=Number(raw);state.kpis=state.kpis.map(item=>item.id===k.id?{...item,actual,history:[...(item.history||[])].filter(h=>h.date!==date).concat({date,actual})}:item)},'Save actual')}
function kpiEditor(k){const status=kpiStatus(k);return `<div class="kpi-editor"><div><span class="kpi-status ${status}"></span><strong>${esc(k.name)}</strong><small>${esc(k.category)} &#183; target ${esc(kpiDisplay(k,k.target))} &#183; actual ${esc(kpiDisplay(k))}</small></div><div class="kpi-editor-actions"><button class="button small" data-edit-kpi="${k.id}">Edit KPI</button><button class="button small delete-link" data-delete-kpi="${k.id}">Delete</button></div></div>`}
function scorecardEvidence(){return `<section class="evidence-dashboard"><div class="evidence-head"><div><div class="section-kicker">KPI &#8594; ROUTINE &#8594; PROOF</div><h2 class="dashboard-section-title">Objective evidence</h2><p class="muted">Keep the baseline, target, action and proof beside the weekly result.</p></div></div><div class="evidence-grid">${state.kpis.map(k=>`<article class="evidence-card"><div class="evidence-card-head"><div><span class="kicker">${esc(k.category)}</span><h3>${esc(k.name)}</h3></div><span class="status ${kpiStatus(k)}">${kpiStatus(k)}</span></div><div class="evidence-metrics"><div><span>Baseline</span><strong>${esc(kpiDisplay(k,k.baseline))}</strong></div><div><span>Target</span><strong>${esc(kpiDisplay(k,k.target))}</strong></div><div><span>Current</span><strong>${esc(kpiDisplay(k,k.actual))}</strong></div></div><dl><div><dt>Linked routine</dt><dd>${esc(k.linkedRoutine||'Scorecard')}</dd></div><div><dt>Routine</dt><dd>${esc(k.routine||'Add the routine that drives this KPI')}</dd></div><div><dt>Actions</dt><dd>${esc(k.actions||'No corrective action recorded')}</dd></div><div><dt>Evidence</dt><dd>${esc(k.evidence||'Add the report, record or proof source')}</dd></div><div><dt>Result</dt><dd>${esc(k.result||'Record the measurable outcome')}</dd></div></dl><div class="evidence-card-actions"><button class="button small" data-management-edit="${esc(k.id)}">Edit KPI</button><button class="button small delete-link" data-delete-kpi="${esc(k.id)}">Delete</button></div></article>`).join('')||'<div class="empty">Create a KPI to start building objective evidence.</div>'}</div></section>`}
function managementKpis(){return `<div class="hero"><div><div class="kicker">CAPTURE &#8594; RECORD &#8594; REPORT</div><h1>Management KPIs</h1><p>Define the measures that matter, record the evidence and print a clear management report.</p></div><div class="scorecard-actions"><button class="button teal" data-add-kpi>&#65291; Create KPI</button><button class="button" data-print-management-kpis>Print report</button></div></div><div class="card management-kpi-intro"><div class="card-head"><div><h2 class="section-title">Management evidence</h2><p class="muted">Each KPI keeps its baseline, target, routine, actions, evidence source and measurable result in one place.</p></div><span class="pill">${state.kpis.length} KPIs</span></div><div class="management-kpi-steps"><div><b>01</b><strong>Define</strong><span>Set the measure, owner, target and colour thresholds.</span></div><div><b>02</b><strong>Record</strong><span>Enter the Friday actual during the weekly review.</span></div><div><b>03</b><strong>Prove</strong><span>Keep the source, action and benefit beside the result.</span></div><div><b>04</b><strong>Report</strong><span>Print this view for a focused management conversation.</span></div></div></div>${scorecardEvidence()}`}
function scorecard(){const rows=state.kpis;const historyDates=[...new Set(state.kpis.flatMap(k=>k.history.map(h=>h.date)).filter(Boolean))].sort();const initialFriday=historyDates[0]||fridayOfWeek();const periods=Array.from({length:12},(_,i)=>addWeeks(initialFriday,i));return `<div class="hero"><div><div class="kicker">MEASURE &#8594; IMPROVE</div><h1>Scorecard</h1><p>See the pattern, not just the point. Exceptions become visible early enough to act.</p></div><div class="scorecard-actions"><button class="button teal" data-weekly-review>&#65291; Enter weekly review</button><button class="button" data-edit-latest>&#9998; Edit latest actuals</button></div></div><div class="scorecard-summary"><div class="summary-chip"><span class="summary-dot good"></span><strong>${state.kpis.filter(k=>kpiStatus(k)==='on-track').length}</strong><span>On track</span></div><div class="summary-chip"><span class="summary-dot amber"></span><strong>${state.kpis.filter(k=>kpiStatus(k)==='at-risk').length}</strong><span>At risk</span></div><div class="summary-chip"><span class="summary-dot bad"></span><strong>${state.kpis.filter(k=>kpiStatus(k)==='off-track').length}</strong><span>Off track</span></div><div class="summary-caption">Fridays &#183; rolling 12-week team focus</div></div><div class="card scorecard-card"><div class="card-head"><div><h2 class="section-title">Leadership scorecard</h2><div class="muted">Weekly team performance by KPI &#183; click a cell to inspect the signal</div></div><div class="score-legend"><span><i class="legend-swatch good"></i>On track</span><span><i class="legend-swatch amber"></i>At risk</span><span><i class="legend-swatch bad"></i>Off track</span></div></div><div class="scorecard-scroll"><div class="scorecard-matrix"><div class="matrix-header"><div class="matrix-label">KPI / owner</div>${periods.map(p=>`<div>${fmt(p)}</div>`).join('')}</div>${rows.map(k=>`<div class="matrix-row"><div class="matrix-label"><span class="kpi-indent">&#8627;</span><span class="kpi-status ${kpiStatus(k)}"></span><span><strong>${esc(k.name)}</strong><small>${esc(k.category)} &#183; ${esc(k.owner||'team focus')}</small></span></div>${periods.map((p,i)=>scoreCell(k,i,p)).join('')}</div>`).join('')||'<div class="empty">Create your first KPI to build the team scorecard.</div>'}</div></div><div class="scorecard-footer"><span>Every KPI is a shared team focus. Amber and red signals should have a corrective action.</span><button class="button small" data-view="ids">Open IDS &#8594;</button></div></div><div class="kpi-controls"><div><div class="section-kicker">YOUR KPIs</div><h2 class="dashboard-section-title">Targets and actuals</h2><p class="muted">Create a KPI once, then update the actual as the work happens. Colour status is calculated automatically from your thresholds.</p></div><button class="button teal" data-add-kpi>&#65291; New KPI</button><div class="kpi-editor-list">${state.kpis.map(kpiEditor).join('')}</div></div>`}
function rocks(){const rocks=state.tasks.filter(t=>t.priority==='high'&&t.status!=='done'),top3=state.eod.top3.split('\n').filter(Boolean);return `<div class="hero"><div><div class="kicker">ALIGN &#8594; EXECUTE</div><h1>Rocks</h1><p>Keep the few priorities that move the team forward visible, owned and connected to today&#8217;s work.</p></div><button class="button teal" data-add-task>+ Add a Rock</button></div><div class="bento"><div class="card span-7"><div class="card-head"><div><h2 class="section-title">Active Rocks</h2><div class="muted">High-priority commitments currently in motion</div></div><span class="pill">${rocks.length} active</span></div><div class="task-list">${rocks.map(taskRow).join('')||'<div class="empty">No active Rocks. Add a high-priority task to set the next one.</div>'}</div></div><div class="card span-5"><div class="card-head"><h2 class="section-title">Top 3 alignment</h2><span class="pill">From EOD</span></div>${top3.map((item,i)=>`<div class="status-row"><div><strong>${String(i+1).padStart(2,'0')} &#183; ${esc(item)}</strong><div class="muted">Ready for the next huddle</div></div><span class="muted">&#8594;</span></div>`).join('')||'<div class="empty">Prepare your Top 3 in End of Day.</div>'}</div><div class="card span-12"><div class="card-head"><div><h2 class="section-title">Rock discipline</h2><div class="muted">A Rock should be specific, important and visible in the weekly rhythm.</div></div><button class="button" data-view="tasks">Open Tasks &#8594;</button></div><div class="rock-principles"><div><strong>Specific</strong><span>One clear outcome the team can recognise.</span></div><div><strong>Owned</strong><span>Someone carries it forward and communicates progress.</span></div><div><strong>Connected</strong><span>It supports a KPI, customer outcome or leadership priority.</span></div></div></div></div>`}
function ids(){return `<div class="hero"><div><div class="kicker">IDENTIFY &#8594; DISCUSS &#8594; SOLVE</div><h1>IDS Workspace</h1><p>Turn the real issue into a clear decision and an owned action.</p></div><button class="button teal" data-add-issue>&#65291; Capture issue</button></div><div class="card"><div class="card-head"><h2 class="section-title">Open issues</h2><span class="pill">${state.issues.length} captured</span></div>${state.issues.length?state.issues.map(i=>`<div class="status-row"><div><strong>${esc(i.title)}</strong><div class="muted">${esc(i.source)} &#183; raised ${fmt(i.date)}</div></div><span class="status at-risk">Identify</span></div>`).join(''):'<div class="empty">No open issues. Capture one when a problem needs a proper discussion.</div>'}</div>`}
function l10(){const health=meetingHealth();return `<div class="hero"><div><div class="kicker">ALIGN THE TEAM</div><h1>L10 Meeting</h1><p>A simple 90-minute operating cadence. Keep the conversation focused and turn actions into tasks.</p></div><button class="button teal" data-toast="Meeting started locally">Start meeting</button></div><div class="bento"><div class="card span-8"><div class="card-head"><h2 class="section-title">Meeting flow</h2><span class="pill">90 min</span></div>${['Segue','Scorecard','Rock Review','Headlines','To-Dos','IDS','Conclude'].map((x,i)=>`<div class="status-row"><span><b style="color:var(--teal)">${String(i+1).padStart(2,'0')}</b> &nbsp;${x}</span><span class="muted">${[5,5,5,5,5,60,5][i]} min &#8594;</span></div>`).join('')}</div><div class="card span-4"><h2 class="section-title">Meeting health</h2><div class="big-number">${health.toFixed(1)}<span class="muted"> / 10</span></div><div class="muted">Last meeting rating</div><div class="progress" style="margin-top:18px"><i style="width:${health*10}%"></i></div><p class="muted">Target: 8+</p></div></div>`}
function applyAppearance(mode){const actual=mode==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):mode;document.documentElement.dataset.theme=actual;document.documentElement.dataset.appearanceMode=mode}
function settingsDialog(){const backdrop=document.createElement('div');backdrop.className='settings-backdrop';backdrop.innerHTML=`<div class="settings-dialog">${settings()}</div>`;document.body.append(backdrop);backdrop.querySelector('[data-view="dashboard"]').onclick=()=>backdrop.remove();backdrop.querySelectorAll('[data-appearance]').forEach(button=>button.onclick=()=>{state.settings={...(state.settings||{}),appearance:button.dataset.appearance};applyAppearance(button.dataset.appearance);save();backdrop.querySelectorAll('[data-appearance]').forEach(item=>item.classList.toggle('active',item===button));toast(`${button.textContent} appearance selected`)});backdrop.querySelector('[data-export]').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='talentisos-backup.json';a.click()};backdrop.querySelector('[data-import]').onclick=()=>backdrop.querySelector('#import-file').click();backdrop.querySelector('#import-file').onchange=e=>{const reader=new FileReader();reader.onload=()=>{try{state=normalizeState(JSON.parse(reader.result));importEodToHuddle();save();backdrop.remove();render();toast('Backup restored; incomplete End of Day items synced to Morning Huddle and Today’s Work')}catch{toast('That backup could not be read')}};reader.readAsText(e.target.files[0])};backdrop.querySelector('[data-csv-export]').onclick=()=>{const type=backdrop.querySelector('#csv-dataset').value,rows=type==='kpis'?[['name','category','target','actual','unit','status'],...state.kpis.map(k=>[k.name,k.category,k.target,k.actual,k.unit,kpiStatus(k)])]:[['title','status','priority','due'],...state.tasks.map(t=>[t.title,t.status,t.priority,t.due])],csvText=rows.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csvText],{type:'text/csv'}));a.download=`talentisos-${type}.csv`;a.click();toast('CSV exported locally')};backdrop.querySelector('[data-csv-import]').onclick=()=>toast('CSV import template is ready for the next data pass');backdrop.querySelectorAll('[data-toast]').forEach(button=>button.onclick=()=>toast(button.dataset.toast));backdrop.querySelectorAll('[data-delete-all]').forEach(button=>button.onclick=()=>deleteAllModal());backdrop.querySelector('[data-save-sync]').onclick=()=>{const value=backdrop.querySelector('#sync-api').value.trim().replace(/\/$/,'');state.settings={...(state.settings||{}),syncApi:value};if(value)localStorage.setItem('talentisos-sync-url',value);else localStorage.removeItem('talentisos-sync-url');save();toast(value?'Sync URL saved':'Cloud sync disabled')};backdrop.querySelector('[data-github-connect]').onclick=()=>{const base=backdrop.querySelector('#sync-api').value.trim().replace(/\/$/,'');if(!base){toast('Save the Worker URL first');return}location.href=`${base}/auth/login`};backdrop.querySelector('[data-github-logout]').onclick=()=>{const base=syncApi();if(base)location.href=`${base}/auth/logout`;else toast('Cloud sync is not configured')}}
function settings(){const pref=state.settings?.appearance||'dark';return `<div class="settings-shell"><div class="settings-hero"><div><div class="kicker">PREFERENCES</div><h1>Settings</h1></div><button class="settings-close" data-view="dashboard" aria-label="Close settings">&#215;</button></div><div class="settings-intro">Tune the interface to the way you work. Your records stay on this device unless you export them.</div><section class="settings-section"><h2>Appearance</h2><div class="appearance-switch"><button class="appearance-choice ${pref==='light'?'active':''}" data-appearance="light">Light</button><button class="appearance-choice ${pref==='system'?'active':''}" data-appearance="system">System</button><button class="appearance-choice ${pref==='dark'?'active':''}" data-appearance="dark">Dark</button></div></section><section class="settings-section"><div class="kicker">SETTINGS &#183; DATA</div><h2>Protect your workspace.</h2><p class="settings-copy">Backups, restores, and imports happen locally. Nothing is uploaded.</p><div class="settings-divider"></div><h3>JSON backup</h3><p class="settings-copy">Export everything needed to rebuild this workspace on another device.</p><button class="button teal settings-wide" data-export>Export backup</button><button class="button" data-import>Restore backup</button><input type="file" id="import-file" accept="application/json" hidden/></section><section class="settings-section"><h3>CSV tools</h3><p class="settings-copy">Move simple lists in and out of TalentisOS when you need a handoff.</p><div class="csv-row"><label>Dataset<select class="select" id="csv-dataset"><option value="tasks">Priorities</option><option value="kpis">Scorecard KPIs</option></select></label><button class="button" data-csv-export>Export CSV</button><button class="text-link" data-toast="CSV template ready to download">Download template</button></div><button class="button" data-csv-import>Import CSV</button><input type="file" id="csv-file" accept=".csv,text/csv" hidden/></section><section class="settings-section sync-section"><div class="kicker">CLOUD SYNC</div><h3>GitHub workspace</h3><p class="settings-copy">Connect securely through the OAuth Worker. Your GitHub token never enters this app.</p><label>Secure sync Worker URL<input class="input" id="sync-api" value="${esc(syncApi())}" placeholder="https://talentisos-sync.example.workers.dev"/></label><div class="settings-actions"><button class="button" data-save-sync>Save sync URL</button><button class="button teal" data-github-connect>Connect GitHub</button><button class="text-link" data-github-logout>Disconnect</button></div></section><section class="settings-section"><h3>Local snapshots</h3><p class="settings-copy">Automatic daily and weekly snapshots rotate on this device.</p><div class="snapshot-row"><div><strong>${new Date().toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})} at ${new Date().toLocaleTimeString('en-AU',{hour:'numeric',minute:'2-digit'})}</strong><small>weekly snapshot &#183; ${state.tasks.length+state.kpis.length} records</small></div><button class="text-link" data-toast="Snapshot restore is available in JSON backup">Restore</button></div></section><section class="settings-section danger-section"><h3>Delete all data</h3><div class="danger-notice"><strong>Warning</strong><span>This cannot be undone. Export a backup before deleting.</span></div><p class="settings-copy">This removes workspace records and cannot be undone. Export a backup first.</p><button class="button danger-button" data-delete-all>Delete all data</button></section><div class="settings-footer"><span>TalentisOS &#183; local-first leadership playbook</span><span>Version 0.1 preview</span></div></div>`}
function tasks(){const open=state.tasks.filter(t=>t.status!=='done');return '<div class="hero"><div><div class="kicker">EXECUTE WITH CLARITY</div><h1>Tasks</h1><p>Keep commitments visible, dated and easy to complete.</p></div><button class="button teal" data-add-task>+ Add a commitment</button></div><div class="card"><div class="card-head"><h2 class="section-title">Open commitments</h2><span class="pill">'+open.length+' open</span></div><label class="search-label">Search<input class="input" id="task-search" placeholder="Find a commitment"/></label><div class="task-list">'+(open.map(taskRow).join('')||'<div class="empty">No open commitments.</div>')+'</div></div>'}
function completedHuddleTimeline(){const completed=state.tasks.filter(t=>t.status==='done'&&(t.movedToHuddleDate||t.movedToTodayDate||t.source==='Huddle'||t.source==='Today'));const groups={};completed.forEach(task=>{const date=task.completedDate||(task.completedAt||'').slice(0,10)||task.movedToTodayDate||task.movedToHuddleDate||'Undated';(groups[date]??=[]).push(task)});const dates=Object.keys(groups).sort((a,b)=>b.localeCompare(a));return '<section class="completed-timeline"><div class="card-head"><div><div class="section-kicker">COMPLETED WORK</div><h2 class="section-title">Completion timeline</h2></div><span class="pill">'+completed.length+' completed</span></div>'+(dates.length?'<div class="completion-timeline">'+dates.map(date=>'<article class="completion-day"><div class="completion-day-marker"></div><div class="completion-day-content"><div class="completion-date">'+esc(date==='Undated'?'Date not recorded':fmt(date))+'</div><div class="completion-items">'+groups[date].map(task=>'<div class="completion-item"><span class="completion-check">&#10003;</span><span>'+esc(task.title)+'</span></div>').join('')+'</div></div></article>').join('')+'</div>':'<div class="empty">Completed Huddle work will appear here by date.</div>')+'</section>'}
function render(){if(!['dashboard','eod','huddle','today','tasks','scorecard','management-kpis','rocks','l10','ids','settings'].includes(current))current='dashboard';layout();const view={dashboard,eod,huddle,today:todayView,tasks,scorecard,'management-kpis':managementKpis,rocks,l10,ids,settings}[current]();document.querySelector('#view').innerHTML=current==='huddle'?view+completedHuddleTimeline():view;bind()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelector('.sidebar').classList.remove('open');if(b.dataset.view==='settings'){settingsDialog();return}current=b.dataset.view;render()});document.querySelectorAll('[data-weekly-cell]').forEach(cell=>{const open=e=>{e?.preventDefault();e?.stopPropagation();const [id,date]=cell.dataset.weeklyCell.split('|');const k=state.kpis.find(item=>item.id===id);if(k)weeklyActualModal(k,date)};cell.onclick=open;cell.ontouchend=open});document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(x=>x.id===b.dataset.complete);if(!t)return;t.status=t.status==='done'?'open':'done';save();render();toast(t.status==='done'?'Commitment completed everywhere':'Commitment reopened')});document.querySelectorAll('[data-add-task]').forEach(b=>b.onclick=()=>taskModal());document.querySelectorAll('[data-add-issue]').forEach(b=>b.onclick=()=>issueModal());document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));document.querySelector('[data-save-eod]')?.addEventListener('click',()=>{const f=new FormData(document.querySelector('#eod-form'));state.eod={...state.eod,...Object.fromEntries(f)};state.eod.top3=document.querySelector('#top3').value;save();toast('End of Day saved locally')});document.querySelector('[data-export]')?.addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='talentisos-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});document.querySelector('[data-import]')?.addEventListener('click',()=>document.querySelector('#import-file').click());document.querySelector('#import-file')?.addEventListener('change',e=>{const r=new FileReader();r.onload=()=>{try{state=normalizeState(JSON.parse(r.result));save();render();toast('Backup restored')}catch{toast('That backup could not be read')}};if(e.target.files[0])r.readAsText(e.target.files[0])});document.querySelector('[data-print-management-kpis]')?.addEventListener('click',()=>window.print());document.querySelector('#task-search')?.addEventListener('input',e=>{const query=e.target.value.toLowerCase();document.querySelectorAll('.task-row').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(query)?'flex':'none')})}
function deleteAllModal(){modal('Delete all data','<div class="danger-notice"><strong>Warning</strong><span>This permanently removes tasks, KPIs, history, notes and settings. This cannot be undone. Export a backup first.</span></div>',()=>{state=emptyWorkspace();document.querySelector('.settings-backdrop')?.remove()},'Delete all data')}
function modal(title,body,submit,label='Add'){document.querySelector('.modal-backdrop')?.remove();const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="modal ${title.toLowerCase().includes('weekly')?'weekly-modal':''}"><h2>${title}</h2>${body}<div class="modal-actions"><button class="button" data-cancel>Cancel</button><button class="button ${label.toLowerCase().includes('delete')?'danger-button':'teal'}" data-submit>${label}</button></div></div>`;document.body.append(b);requestAnimationFrame(()=>b.querySelector('input:not([readonly]),select:not([disabled]),textarea')?.focus());b.querySelector('[data-cancel]').onclick=()=>b.remove();b.querySelector('[data-submit]').onclick=()=>{submit(b);b.remove();save();render();toast('Saved locally')};}
function todayItemModal(){modal('Add to Today&#8217;s checklist','<div class="form"><label>What needs to move forward?<input class="input" name="title" placeholder="Add today&#8217;s commitment" autofocus/></label><label>Priority<select class="select" name="priority"><option value="high">High priority</option><option value="medium" selected>Medium priority</option><option value="low">Low priority</option></select></label></div>',m=>{const title=m.querySelector('[name=title]').value.trim();if(!title)return;const now=new Date().toISOString();state.tasks.push({id:'today-'+Date.now(),title,due:today(),priority:m.querySelector('[name=priority]').value,status:'open',carry:0,source:'Today',createdAt:now,createdDate:today(),movedToTodayAt:now,movedToTodayDate:today()})},'Add item')}
document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-add-today]'):null;if(button)todayItemModal()},true);
function taskModal(existing){const t=existing||{title:'',due:today(),priority:'medium',source:'Today'};modal(existing?'Edit task':'Add a commitment',`<div class="form"><label>Task title<input class="input" name="title" placeholder="What needs to move forward?" value="${esc(t.title)}" autofocus/></label><label>Due date<input class="input" name="due" type="date" value="${t.due||today()}"/></label><label>Priority<select class="select" name="priority"><option value="high" ${t.priority==='high'?'selected':''}>High priority</option><option value="medium" ${t.priority==='medium'?'selected':''}>Medium priority</option><option value="low" ${t.priority==='low'?'selected':''}>Low priority</option></select></label></div>`,m=>{const title=m.querySelector('[name=title]').value.trim();if(!title)return;const updated={...t,id:t.id||'t'+Date.now(),title,due:m.querySelector('[name=due]').value,priority:m.querySelector('[name=priority]').value,status:t.status||'open',carry:t.carry||0,source:t.source||'Today'};if(existing)state.tasks=state.tasks.map(item=>item.id===existing.id?updated:item);else state.tasks.push(updated)})}
function deleteTaskModal(t){modal('Delete task',`<div class="danger-notice"><strong>Warning</strong><span>Delete “${esc(t.title)}”? This cannot be undone.</span></div>`,()=>{state.tasks=state.tasks.filter(item=>item.id!==t.id)},'Delete task')}
function issueModal(){modal('Capture an issue',`<div class="form"><input class="input" name="title" placeholder="What is the real issue?" autofocus/><input class="input" name="source" value="Today&#8217;s Work"/></div>`,m=>{const title=m.querySelector('[name=title]').value.trim();if(title)state.issues.push({id:'i'+Date.now(),title,source:m.querySelector('[name=source]').value,date:today()})})}
function kpiModal(existing){if(!existing)return simpleKpiModal();}
function simpleKpiModal(existing){const k=existing||{name:'',category:'',target:'',actual:'',warning:'',red:'',unit:'',direction:'higher'};const areas=['Customer Care','Service Controller','Help Desk','Operations','Leadership','Other'];modal(existing?'Update KPI':'Create KPI',`<div class="form"><input class="input" name="name" placeholder="KPI name" value="${esc(k.name)}" autofocus/><select class="select" name="category"><option value="">Area / function</option>${areas.map(area=>`<option value="${esc(area)}" ${k.category===area?'selected':''}>${esc(area)}</option>`).join('')}</select><div class="form-two"><label>Target<input class="input" name="target" type="number" step="any" value="${k.target??''}" placeholder="Target"></label></div><div class="form-two"><label>Amber threshold<input class="input" name="warning" type="number" step="any" value="${k.warning??''}" placeholder="Warning"></label><label>Red threshold<input class="input" name="red" type="number" step="any" value="${k.red??''}" placeholder="Off track"></label></div><div class="form-two"><label>Unit / suffix<input class="input" name="unit" value="${esc(k.unit||'')}" placeholder="%, hrs, / week"></label><label>Better when<select class="select" name="direction"><option value="higher" ${k.direction==='higher'?'selected':''}>Higher is better</option><option value="lower" ${k.direction==='lower'?'selected':''}>Lower is better</option></select></label></div><p class="muted form-hint">Enter the measure once. You can add evidence, actions and a linked routine from Management KPIs.</p></div>`,m=>{const value=field=>m.querySelector(`[name=${field}]`).value;const actual=existing?k.actual:'';const updated={...k,id:k.id||'k'+Date.now(),category:value('category').trim()||'General',name:value('name').trim()||'Untitled KPI',purpose:k.purpose||'Management KPI',owner:k.owner||'Team focus',target:Number(value('target'))||0,warning:Number(value('warning'))||0,red:Number(value('red'))||0,unit:value('unit'),direction:value('direction'),actual,history:k.history||[]};if(existing)state.kpis=state.kpis.map(item=>item.id===existing.id?updated:item);else state.kpis.push(updated)},'Create KPI')}
function advancedKpiModal(existing){const k=existing||{name:'',category:'',purpose:'',owner:'',routine:'',linkedRoutine:'Scorecard',baseline:'',evidence:'',actions:'',result:'',target:'',warning:'',red:'',unit:'',direction:'higher',actual:''};modal(existing?'Update KPI':'Create KPI',`<div class="form"><input class="input" name="name" placeholder="KPI name" value="${esc(k.name)}" autofocus/><input class="input" name="category" placeholder="Category / function" value="${esc(k.category)}"/><input class="input" name="owner" placeholder="Owner role" value="${esc(k.owner)}"/><select class="select" name="linkedRoutine"><option value="">Link to a Talentis routine</option><option value="End of Day" ${k.linkedRoutine==='End of Day'?'selected':''}>End of Day</option><option value="Morning Huddle" ${k.linkedRoutine==='Morning Huddle'?'selected':''}>Morning Huddle</option><option value="Today's Work" ${k.linkedRoutine==="Today's Work"?'selected':''}>Today's Work</option><option value="Rocks" ${k.linkedRoutine==='Rocks'?'selected':''}>Rocks</option><option value="Tasks" ${k.linkedRoutine==='Tasks'?'selected':''}>Tasks</option><option value="Scorecard" ${k.linkedRoutine==='Scorecard'?'selected':''}>Scorecard</option><option value="L10 Meeting" ${k.linkedRoutine==='L10 Meeting'?'selected':''}>L10 Meeting</option><option value="IDS" ${k.linkedRoutine==='IDS'?'selected':''}>IDS</option></select><input class="input" name="routine" placeholder="Routine that drives this KPI" value="${esc(k.routine||'')}"/><div class="form-two"><label>Baseline<input class="input" name="baseline" type="number" step="any" value="${k.baseline??''}"></label><label>Evidence source<input class="input" name="evidence" placeholder="Report, register or record" value="${esc(k.evidence||'')}"></label></div><label>Actions taken<textarea class="textarea" name="actions" placeholder="What changed or was improved?">${esc(k.actions||'')}</textarea></label><label>Result / benefit<textarea class="textarea" name="result" placeholder="What measurable outcome proves progress?">${esc(k.result||'')}</textarea></label><div class="form-two"><label>Target<input class="input" name="target" type="number" step="any" value="${k.target}"></label><label>Actual<input class="input" name="actual" type="number" step="any" value="${k.actual}"></label></div><div class="form-two"><label>Amber threshold<input class="input" name="warning" type="number" step="any" value="${k.warning}"></label><label>Red threshold<input class="input" name="red" type="number" step="any" value="${k.red}"></label></div><div class="form-two"><label>Unit / suffix<input class="input" name="unit" placeholder="%, hrs, / week" value="${esc(k.unit)}"></label><label>Better when<select class="select" name="direction"><option value="higher" ${k.direction==='higher'?'selected':''}>Higher is better</option><option value="lower" ${k.direction==='lower'?'selected':''}>Lower is better</option></select></label></div><p class="muted form-hint">The actual is compared with target and thresholds automatically. Higher-is-better KPIs turn green at or above target; lower-is-better KPIs turn green at or below target.</p></div>`,m=>{const value=field=>m.querySelector(`[name=${field}]`).value;const actual=value('actual')===''?'':Number(value('actual'));const updated={...k,id:k.id||'k'+Date.now(),name:value('name').trim()||'Untitled KPI',category:value('category').trim()||'General',owner:value('owner').trim()||'Owner role',linkedRoutine:value('linkedRoutine'),routine:value('routine').trim(),baseline:value('baseline')===''?'':Number(value('baseline')),evidence:value('evidence').trim(),actions:value('actions').trim(),result:value('result').trim(),target:Number(value('target'))||0,warning:Number(value('warning'))||0,red:Number(value('red'))||0,unit:value('unit'),direction:value('direction'),actual,history:k.history||[]};if(existing&&actual!==k.actual&&actual!==''){const date=latestKpiDate(k);updated.history=[...updated.history.filter(h=>h.date!==date),{date,actual}]};if(existing)state.kpis=state.kpis.map(item=>item.id===existing.id?updated:item);else state.kpis.push(updated)})}
function deleteKpiModal(k){modal('Delete KPI',`<div class="danger-notice"><strong>Warning</strong><span>Delete “${esc(k.name)}” and its weekly history? This cannot be undone. Export a backup first.</span></div>`,()=>{state.kpis=state.kpis.filter(item=>item.id!==k.id)},'Delete KPI')}
function weeklyReviewModal(editLatest=false){const existingDates=[...new Set(state.kpis.flatMap(k=>k.history.map(h=>h.date)).filter(Boolean))].sort();const weekEnding=editLatest?(existingDates.at(-1)||fridayOfWeek()):fridayOfWeek();const areas=['Customer Care','Service Controller','Help Desk','Operations','Leadership','Other'];modal(editLatest?'Edit weekly KPI actuals':'Weekly KPI review',`<div class="weekly-review-intro"><p>${editLatest?'Update the saved values for a Friday. Saving replaces that week&#8217;s entries.':'Capture this week&#8217;s team KPI results in one quick pass. Week-ending dates are kept to Friday.'}</p></div><div class="form"><label>Week ending Friday<input class="input" name="weekEnding" type="date" value="${weekEnding}" required/></label><div class="weekly-kpi-table"><div class="weekly-kpi-table-head"><span>KPI</span><span>Area</span><span>Target</span><span>Actual</span></div>${state.kpis.map(k=>{const saved=k.history.find(h=>h.date===weekEnding);return`<div class="weekly-kpi-row"><input class="input" name="name-${k.id}" value="${esc(k.name)}" placeholder="KPI name" aria-label="KPI name" readonly/><select class="select" name="category-${k.id}" disabled>${areas.map(area=>`<option value="${esc(area)}" ${(k.category||'')===area?'selected':''}>${esc(area)}</option>`).join('')}</select><input class="input" name="target-${k.id}" type="number" step="any" value="${k.target??''}" aria-label="Target for ${esc(k.name)}" readonly/><input class="input" name="actual-${k.id}" type="number" step="any" value="${saved?.actual??(editLatest?k.actual:'')}" placeholder="Actual" aria-label="Actual for ${esc(k.name)}"/></div>`}).join('')||'<div class="empty">Create a KPI before starting a weekly review.</div>'}</div><p class="muted form-hint">Status colours are calculated automatically from each KPI&#8217;s target, warning threshold, red threshold and direction.</p></div>`,m=>{const date=fridayOfWeek(m.querySelector('[name=weekEnding]').value||weekEnding);state.kpis=state.kpis.map(k=>{const name=m.querySelector(`[name=name-${k.id}]`)?.value.trim()||'Untitled KPI',category=m.querySelector(`[name=category-${k.id}]`)?.value||k.category||'General',targetRaw=m.querySelector(`[name=target-${k.id}]`)?.value??'',actualRaw=m.querySelector(`[name=actual-${k.id}]`)?.value??'',target=targetRaw===''?k.target:Number(targetRaw),history=[...(k.history||[])].filter(h=>h.date!==date);if(actualRaw==='')return {...k,name,category,target,actual:k.actual,history};const actual=Number(actualRaw);return {...k,name,category,target,actual,history:[...history,{date,actual}]}})},'Save weekly review')}
function guideContent(view){const guides={"management-kpis":["Management KPIs guide","Capture, record, prove and report the measures that matter.",[["Define","Create a KPI with its owner, baseline, target, direction and colour thresholds."],["Record","Use the Scorecard weekly review to enter the achieved Friday actual."],["Evidence","Keep the routine, evidence source, actions and result beside each KPI."],["Report","Use Print report for a focused management conversation."]]],dashboard:['Dashboard guide','Command centre for the leadership rhythm.',[['Metric tiles','Open commitments counts unfinished tasks. Top 3 ready counts priorities from End of Day. KPI exceptions counts amber, red or unreported KPIs. Rhythm shows the weekly cadence. Tap a tile for detail.'],['Focus cards','Available Today shows the first open commitment. Tomorrow\'s Top 3 comes from End of Day. Scorecard pulse opens the scorecard. Leadership rhythm opens the huddle.']]],eod:['End of Day guide','Close the loop while the day is still fresh.',[['Daily close','Record completed work, outstanding work, risks, customer issues, blockers and handovers.'],['Top 3','Enter up to three priorities, one per line. Save the close to carry the handover into the huddle.']]],huddle:['Morning Huddle guide','Turn yesterday\'s close into today\'s alignment.',[['Carry-over commitments','Open tasks are canonical commitments. Completing one here completes it everywhere.'],['Prompts','Use Top 3, risks, recognition and commitments to keep the conversation focused.']]],today:['Today\'s Work guide','Keep execution narrow and visible.',[['Top 3 priorities','The task list is the single source of truth for today\'s commitments.'],['Execution check','Completion percentage equals completed tasks divided by total tasks, multiplied by 100.']]],rocks:['Rocks guide','Keep the few priorities that move the team forward visible.',[['Active Rocks','Active Rocks are unfinished high-priority tasks. Add a Rock creates a high-priority task.'],['Discipline','A Rock should be specific, owned and connected to a KPI, customer outcome or leadership priority.']]],tasks:['Tasks guide','Your one source of truth for commitments.',[['Task actions','Search tasks, review due dates and priorities, and use the check control to complete or reopen work.'],['Shared status','Task completion is reflected in Dashboard, Huddle, Today\'s Work and Rocks.']]],scorecard:['Scorecard guide','Review weekly performance by KPI and act on exceptions.',[['Matrix','Each row is one flat team KPI. Columns are Friday week-ending dates.'],['Colour logic','Higher is better: green at or above target, amber at or above warning, red below warning. Lower is better: green at or below target, amber at or below warning, red above warning.'],['Weekly review','Enter actuals and a week-ending date. The date is normalised to Friday and saved to KPI history. Editing latest actuals replaces that Friday\'s values.']]],l10:['L10 Meeting guide','A practical operating cadence for the team based on EOS.',[['What L10 means','In EOS, the Level 10 Meeting is a recurring weekly leadership meeting designed to keep the team aligned, surface issues early and turn discussion into action. The goal is a focused, useful meeting that the team would rate highly, not a perfect score.'],['Flow','Segue, Scorecard, Rock Review, Headlines, To-Dos, IDS and Conclude keep the meeting focused.'],['IDS theory','Identify, Discuss and Solve is the EOS issue-solving discipline: name the real issue, discuss it without jumping to symptoms, then agree the solution and owned next action.']]],ids:['IDS guide','Turn a real issue into a clear decision and owned action.',[['Issue flow','Capture, identify, discuss, solve and act. Amber and red KPI signals belong here when they need corrective action.']]],settings:['Settings guide','Tune the interface and protect your local workspace.',[['Appearance','Light, System and Dark change the theme and save locally.'],['Data','JSON backup exports the workspace. Restore imports a local backup. CSV tools export task or KPI data.']] ]};return guides[view]||guides.dashboard}
function guideModal(){document.querySelector('.guide-backdrop')?.remove();const key=document.querySelector('.settings-dialog')?'settings':current,[title,intro,sections]=guideContent(key),backdrop=document.createElement('div');backdrop.className='guide-backdrop';backdrop.innerHTML=`<section class="guide-dialog" role="dialog" aria-modal="true" aria-labelledby="guide-title"><div class="guide-head"><div><div class="kicker">TALENTISOS · USER GUIDE</div><h2 id="guide-title">${title}</h2><p>${intro}</p></div><button class="guide-close" data-guide-close aria-label="Close guide">&#215;</button></div><div class="guide-sections">${sections.map(([heading,copy])=>`<article><h3>${heading}</h3><p>${copy}</p></article>`).join('')}</div><div class="guide-foot"><span>Local-first leadership playbook</span><button class="button teal" data-guide-close>Done</button></div></section>`;document.body.append(backdrop);backdrop.querySelectorAll('[data-guide-close]').forEach(button=>button.onclick=()=>backdrop.remove());backdrop.onclick=e=>{if(e.target===backdrop)backdrop.remove()}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.guide-backdrop')?.remove()});
document.addEventListener('click',e=>{const tile=closestFromEvent(e,'[data-metric]');if(!tile)return;const panel=document.querySelector('#metric-detail');if(!panel)return;const same=panel.dataset.open===tile.dataset.metric&&!panel.hidden;document.querySelectorAll('[data-metric]').forEach(item=>{item.classList.remove('active');item.setAttribute('aria-expanded','false')});if(same){panel.hidden=true;panel.dataset.open='';return}panel.innerHTML=metricDetails(tile.dataset.metric);panel.hidden=false;panel.dataset.open=tile.dataset.metric;tile.classList.add('active');tile.setAttribute('aria-expanded','true');panel.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{current=button.dataset.view;render()})});
document.addEventListener('click',e=>{const editTask=closestFromEvent(e,'[data-edit-task]'),deleteTask=closestFromEvent(e,'[data-delete-task]');if(editTask){const t=state.tasks.find(item=>item.id===editTask.dataset.editTask);if(t)taskModal(t)}if(deleteTask){const t=state.tasks.find(item=>item.id===deleteTask.dataset.deleteTask);if(t)deleteTaskModal(t)}});
document.addEventListener('click',e=>{const add=closestFromEvent(e,'[data-add-kpi]'),edit=closestFromEvent(e,'[data-edit-kpi]'),managementEdit=closestFromEvent(e,'[data-management-edit]'),del=closestFromEvent(e,'[data-delete-kpi]');if(add)simpleKpiModal();if(edit){const k=state.kpis.find(item=>item.id===edit.dataset.editKpi);if(k)simpleKpiModal(k)}if(managementEdit){const k=state.kpis.find(item=>item.id===managementEdit.dataset.managementEdit);if(k)advancedKpiModal(k)}if(del){const k=state.kpis.find(item=>item.id===del.dataset.deleteKpi);if(k)deleteKpiModal(k)}});
document.addEventListener('click',e=>{const cell=closestFromEvent(e,'[data-weekly-cell]'),del=closestFromEvent(e,'[data-delete-weekly]');if(closestFromEvent(e,'[data-weekly-review]'))weeklyReviewModal();if(closestFromEvent(e,'[data-edit-latest]'))weeklyReviewModal(true);if(cell){const [id,date]=cell.dataset.weeklyCell.split('|');const k=state.kpis.find(item=>item.id===id);if(k)weeklyActualModal(k,date)}if(del){const [id,date]=del.dataset.deleteWeekly.split('|');state.kpis=state.kpis.map(k=>{if(k.id!==id)return k;const history=(k.history||[]).filter(item=>item.date!==date);return {...k,actual:history.length?k.actual:'',history}});document.querySelector('.modal-backdrop')?.remove();save();render();toast('Weekly actual deleted and Scorecard refreshed')}});
document.addEventListener('click',e=>{if(closestFromEvent(e,'.settings-dialog'))return;const appearance=closestFromEvent(e,'.appearance-choice[data-appearance]'),del=closestFromEvent(e,'[data-delete-all]'),csv=closestFromEvent(e,'[data-csv-export]'),csvImport=closestFromEvent(e,'[data-csv-import]');if(appearance){document.querySelectorAll('.appearance-choice[data-appearance]').forEach(b=>b.classList.remove('active'));appearance.classList.add('active');state.settings={...(state.settings||{}),appearance:appearance.dataset.appearance};applyAppearance(appearance.dataset.appearance);save();toast(`${appearance.textContent} appearance selected`)}if(del){deleteAllModal();return}if(csv){const type=document.querySelector('#csv-dataset')?.value||'tasks',rows=type==='kpis'?[['name','category','target','actual','unit','status'],...state.kpis.map(k=>[k.name,k.category,k.target,k.actual,k.unit,kpiStatus(k)])]:[['title','status','priority','due'],...state.tasks.map(t=>[t.title,t.status,t.priority,t.due])];const csvText=rows.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csvText],{type:'text/csv'}));a.download=`talentisos-${type}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV exported locally')}if(csvImport)toast('CSV import template is ready for the next data pass')});
let mobileMenu=document.querySelector('#mobile-menu'); if(!mobileMenu){mobileMenu=document.createElement('button');mobileMenu.id='mobile-menu';mobileMenu.className='icon-button mobile-menu-fallback';mobileMenu.type='button';mobileMenu.textContent='☰';mobileMenu.setAttribute('aria-label', 'Open navigation');document.body.appendChild(mobileMenu)}
const sidebar=document.querySelector('.sidebar');
const setMobileMenu=(open)=>{if(!mobileMenu||!sidebar)return;sidebar.classList.toggle('open',open);mobileMenu.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open)};
mobileMenu?.setAttribute('aria-controls','primary-navigation');
mobileMenu?.setAttribute('aria-expanded','false');
mobileMenu?.addEventListener('click',()=>setMobileMenu(!sidebar?.classList.contains('open')));
sidebar?.setAttribute('id','primary-navigation');
sidebar?.setAttribute('role','navigation');
sidebar?.setAttribute('aria-label','Primary navigation');
sidebar?.addEventListener('click',event=>{if(event.target.closest('[data-view]'))setMobileMenu(false)});
document.addEventListener('click',event=>{if(sidebar?.classList.contains('open')&&!sidebar.contains(event.target)&&!mobileMenu?.contains(event.target))setMobileMenu(false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape')setMobileMenu(false)});
window.addEventListener('resize',()=>{if(window.innerWidth>1024)setMobileMenu(false)},{passive:true});
document.querySelector('#help-button').onclick=()=>guideModal();document.querySelector('#scroll-top').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});document.querySelector('#scroll-bottom').onclick=()=>window.scrollTo({top:document.documentElement.scrollHeight,behavior:'smooth'});
;(async()=>{state=await load();const migrated=taskEngineMigration();const imported=importEodToHuddle();const huddleSynced=syncHuddleToToday();if(migrated||imported||huddleSynced)await save();applyAppearance(state.settings?.appearance||'dark');render()})();

function restoreSnapshotData(){try{const raw=localStorage.getItem('talentisos-snapshot');return raw?normalizeState(JSON.parse(raw)):cloneData(state)}catch{return cloneData(state)}}
function snapshotDescription(snapshot){return `${snapshot.tasks.length} task${snapshot.tasks.length===1?'':'s'}, ${snapshot.kpis.length} KPI${snapshot.kpis.length===1?'':'s'} and ${snapshot.issues.length} issue${snapshot.issues.length===1?'':'s'}`}
function restoreSnapshotModal(){const snapshot=restoreSnapshotData();modal('Restore workspace',`<div class="restore-notice"><span class="restore-icon">↶</span><div><strong>Restore this local snapshot?</strong><p>This will replace the current workspace with <b>${esc(snapshotDescription(snapshot))}</b>. Your current data will not be changed unless you confirm.</p></div></div>`,()=>{state=normalizeState(snapshot);importEodToHuddle();setTimeout(()=>infoModal('Data restored','Your local workspace has been restored successfully. Any incomplete End of Day items are now available in Morning Huddle and Today’s Work.'),0)},'Yes, restore')}
function infoModal(title,message){document.querySelector('.modal-backdrop')?.remove();const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<div class="modal info-modal" role="dialog" aria-modal="true" aria-labelledby="info-modal-title"><h2 id="info-modal-title">${esc(title)}</h2><p class="info-modal-copy">${esc(message)}</p><div class="modal-actions"><button class="button teal" data-info-ok>OK</button></div></div>`;document.body.append(backdrop);backdrop.querySelector('[data-info-ok]').onclick=()=>backdrop.remove()}
function ensureRestoreSnapshot(){if(!state)return setTimeout(ensureRestoreSnapshot,50);try{if(!localStorage.getItem('talentisos-snapshot'))localStorage.setItem('talentisos-snapshot',JSON.stringify(state))}catch{}}
ensureRestoreSnapshot();
document.addEventListener('click',event=>{const restore=event.target instanceof Element?event.target.closest('.snapshot-row [data-toast]'):null;if(!restore)return;event.preventDefault();event.stopPropagation();restoreSnapshotModal()},true);
function downloadCsvTemplate(){const type=document.querySelector('#csv-dataset')?.value||'tasks';const headers=type==='kpis'?['name','category','purpose','owner','target','warning','red','unit','direction','actual']:['title','status','priority','due','source'];const csv=`${headers.join(',')}\n`;const anchor=document.createElement('a');anchor.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));anchor.download=`talentisos-${type}-template.csv`;anchor.click();setTimeout(()=>URL.revokeObjectURL(anchor.href),1000);toast('CSV template downloaded locally')}
document.addEventListener('click',event=>{const template=event.target instanceof Element?event.target.closest('.csv-row [data-toast]'):null;if(template){event.preventDefault();event.stopPropagation();downloadCsvTemplate();return}const close=event.target instanceof Element?event.target.closest('.settings-close'):null;if(close){event.preventDefault();event.stopPropagation();document.querySelector('.settings-backdrop')?.remove()}},true);
document.addEventListener('click',event=>{const saveClose=event.target instanceof Element?event.target.closest('[data-save-eod]'):null;if(!saveClose)return;event.preventDefault();event.stopPropagation();const form=document.querySelector('#eod-form');if(form){const values=Object.fromEntries(new FormData(form));state.eod={...state.eod,...values};state.eod.top3=document.querySelector('#top3')?.value||''}const hasData=Object.values(state.eod).some(value=>String(value||'').trim());if(hasData){const savedEod={...state.eod,id:`eod-${Date.now()}`,savedAt:new Date().toISOString()};state.eodHistory=[...(state.eodHistory||[]),savedEod];importEodToHuddle()}state.eod={completed:'',outstanding:'',risks:'',top3:'',handovers:''};void save().then(()=>{render();infoModal('End of Day saved','Your daily close has been saved locally and the active form is ready for a new day. Carry-forward items are now available in Morning Huddle and Today’s Work.')})},true);
const brand=document.querySelector('.brand');if(brand){brand.setAttribute('role','button');brand.setAttribute('tabindex','0');brand.setAttribute('aria-label','Go to Today');const goDashboard=()=>{document.querySelector('.settings-backdrop')?.remove();current='today';render()};brand.addEventListener('click',goDashboard);brand.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();goDashboard()}})}

function eodHistoryTimeline(){const history=[...(state.eodHistory||[])].sort((a,b)=>Date.parse(b.savedAt||0)-Date.parse(a.savedAt||0));if(!history.length)return '<section class="eod-history"><div class="eod-history-heading"><div><div class="section-kicker">REVIEW TRAIL</div><h2 class="section-title">End of Day history</h2></div></div><div class="eod-history-empty">Saved daily closes will appear here as a simple timeline.</div></section>';return `<section class="eod-history"><div class="eod-history-heading"><div><div class="section-kicker">REVIEW TRAIL</div><h2 class="section-title">End of Day history</h2></div><span class="pill">${history.length} saved</span></div><div class="eod-timeline">${history.map(entry=>{const date=entry.savedAt?new Date(entry.savedAt).toLocaleString('en-AU',{weekday:'short',day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'}):'Saved close';const points=[['Completed',entry.completed],['Outstanding',entry.outstanding],['Risks',entry.risks],['Top 3',entry.top3],['Handovers',entry.handovers]].filter(([,value])=>String(value||'').trim());return `<article class="eod-timeline-item"><div class="eod-timeline-marker"></div><div class="eod-timeline-card"><div class="eod-timeline-meta">${esc(date)}</div><h3>Daily close saved</h3><div class="eod-timeline-points">${points.map(([label,value])=>`<div><strong>${esc(label)}</strong><span>${esc(value)}</span></div>`).join('')||'<span class="muted">No notes recorded.</span>'}</div></div></article>`}).join('')}</div></section>`;}

function latestEodSource(){return state.eodHistory?.[state.eodHistory.length-1]||state.eod||{}}
