function render(){if(!['dashboard','eod','huddle','today','tasks','scorecard','management-kpis','rocks','l10','ids','settings'].includes(current))current='dashboard';layout();const view={dashboard,eod,huddle,today:todayView,tasks,scorecard,'management-kpis':managementKpis,rocks,l10,ids,settings}[current]();const focusView=current==='dashboard'?view.replace(/(<h2 class="dashboard-section-title">What needs your attention<\/h2><div class="task-list">)[\s\S]*?(<\/div><\/div><div class="dashboard-note">)/,'$1'+dashboardFocusMarkup()+'$2'):view;document.querySelector('#view').innerHTML=current==='huddle'?focusView+completedHuddleTimeline():focusView;bind()}
