function tasks(){const open=sortedOpenTasks(),visible=open.slice(0,5),groups=['high','medium','low'];const body=taskGroupMode==='none'?visible.map(taskRow).join(''):groups.map(priority=>{const items=visible.filter(task=>task.priority===priority);return items.length?'<section class="task-priority-group"><div class="carry-group-heading"><h3>'+priorityLabel(priority)+'</h3><span class="pill">'+items.length+'</span></div>'+items.map(taskRow).join('')+'</section>':''}).join('');return '<div class="hero"><div><div class="kicker">EXECUTE WITH CLARITY</div><h1>Tasks</h1><p>Prioritise commitments, then work the list from high to low.</p></div><button class="button teal" data-add-task>+ Add a commitment</button></div><div class="card"><div class="card-head"><div><h2 class="section-title">Open commitments</h2><span class="muted">Showing '+Math.min(open.length,5)+' of '+open.length+'</span></div><div class="task-filters"><label>Sort<select class="select" id="task-sort"><option value="priority" '+(taskSortMode==='priority'?'selected':'')+'>Priority</option><option value="due" '+(taskSortMode==='due'?'selected':'')+'>Due date</option><option value="title" '+(taskSortMode==='title'?'selected':'')+'>Title</option></select></label><label>Group<select class="select" id="task-group"><option value="priority" '+(taskGroupMode==='priority'?'selected':'')+'>Priority</option><option value="none" '+(taskGroupMode==='none'?'selected':'')+'>No grouping</option></select></label></div></div><label class="search-label">Search<input class="input" id="task-search" placeholder="Find a commitment"/></label><div class="task-list">'+(body||'<div class="empty">No open commitments.</div>')+'</div></div>'}
