function eodLines(value){return String(value||'').split(/\r?\n/).map(item=>item.trim()).filter(Boolean)}
function importEodToHuddle(){const source=latestEodSource(),groups=[['Outstanding',source.outstanding],['Risk / blocker',source.risks],['Handover',source.handovers],['Top 3',source.top3]],movedAt=new Date().toISOString();let added=0;for(const [label,value] of groups)for(const line of eodLines(value)){const title=label+': '+line;if(state.tasks.some(task=>task.title===title&&task.status!=='done'))continue;state.tasks.push({id:'eod-'+Date.now()+'-'+added,title,status:'open',priority:label==='Risk / blocker'?'high':'medium',due:today(),carry:0,source:'End of Day',eodCategory:label.toLowerCase().replaceAll(' ','-'),movedToHuddleAt:movedAt,movedToHuddleDate:today()});added++}return added}
