function eodGroupLabel(task){if(task.eodCategory==='outstanding'||task.title.startsWith('Outstanding:'))return'Outstanding work';if(task.eodCategory?.startsWith('risk')||task.title.startsWith('Risk / blocker:'))return'Risks / blockers';if(task.eodCategory==='handover'||task.title.startsWith('Handover:'))return'Handovers / notes';if(task.eodCategory==='top-3'||task.title.startsWith('Top 3:'))return'Top 3';return'Other End of Day work'}
