function taskCompletedDate(task){return task.completedDate||(task.completedAt||'').slice(0,10)||'Undated'}
function importEodToHuddle(){const source=latestEodSource(),groups=[['Outstanding',source.outstanding],['Risk / blocker',source.risks],['Handover',source.handovers],['Top 3',source.top3]],movedAt=new Date().toISOString(),createdDate=today();let added=0;for(const [label,value] of groups)for(const line of eodLines(value)){const title=label+': '+line,workflowKey=`eod:${createdDate}:${label}:${line}`.toLowerCase();let task=state.tasks.find(item=>item.workflowKey===workflowKey||item.title===title&&item.status!=='done');if(task){const wasSynced=task.movedToHuddleDate===createdDate&&task.movedToTodayDate===createdDate;const history=Array.isArray(task.history)?task.history:[];task.workflowKey=task.workflowKey||workflowKey;task.source='End of Day';task.eodCategory=label.toLowerCase().replaceAll(' ','-');task.committedDate=createdDate;task.movedToHuddleAt=task.movedToHuddleAt||movedAt;task.movedToHuddleDate=task.movedToHuddleDate||createdDate;task.movedToTodayAt=task.movedToTodayAt||movedAt;task.movedToTodayDate=task.movedToTodayDate||createdDate;task.lastUpdated=movedAt;delete task.movedToEodAt;delete task.movedToEodDate;if(!wasSynced&&!history.some(event=>event.event==='Imported from End of Day'&&event.date===createdDate)){task.history=[...history,{at:movedAt,date:createdDate,event:'Imported from End of Day'}];task.carryOverCount=Number(task.carryOverCount||task.carry||0)+1;added++}continue}state.tasks.push({id:'eod-'+Date.now()+'-'+added,title,status:'open',priority:label==='Risk / blocker'?'high':'medium',due:createdDate,carry:0,carryOverCount:0,source:'End of Day',workflowKey,eodCategory:label.toLowerCase().replaceAll(' ','-'),createdAt:movedAt,createdDate,committedDate:createdDate,lastUpdated:movedAt,history:[{at:movedAt,date:createdDate,event:'Imported from End of Day'}],movedToHuddleAt:movedAt,movedToHuddleDate:createdDate,movedToTodayAt:movedAt,movedToTodayDate:createdDate});added++}return added}
function completedHuddleTimeline(){const completed=state.tasks.filter(t=>t.status==='done'&&(t.movedToHuddleDate||t.movedToTodayDate||t.source==='Huddle'||t.source==='Today'));const groups={};completed.forEach(task=>{const date=taskCompletedDate(task),category=eodGroupLabel(task);(groups[date]??={})[category]??=[];groups[date][category].push(task)});const dates=Object.keys(groups).sort((a,b)=>b.localeCompare(a)),categoryOrder=['Outstanding work','Risks / blockers','Handovers / notes','Top 3','Other End of Day work'];return '<section class="completed-timeline"><div class="card-head"><div><div class="section-kicker">COMPLETED WORK</div><h2 class="section-title">Completion timeline</h2></div><span class="pill">'+completed.length+' completed</span></div>'+(dates.length?'<div class="completion-timeline">'+dates.map(date=>'<article class="completion-day"><div class="completion-day-marker"></div><div class="completion-day-content"><div class="completion-date"><span>'+esc(completionDateLabel(date))+'</span><span class="pill">'+Object.values(groups[date]).flat().length+' completed</span></div>'+categoryOrder.filter(category=>groups[date][category]?.length).map(category=>'<section class="completion-group"><div class="completion-group-heading"><h3>'+category+'</h3><span class="pill">'+groups[date][category].length+'</span></div><div class="completion-items">'+groups[date][category].map(task=>'<div class="completion-item"><span class="completion-check">&#10003;</span><div class="completion-item-copy"><span>'+esc(task.title)+'</span><small>Created '+esc(taskCreatedDate(task)==='Undated'?'date not recorded':completionDateLabel(taskCreatedDate(task)))+' &#183; Completed '+esc(taskCompletedDate(task)==='Undated'?'date not recorded':completionDateLabel(taskCompletedDate(task)))+'</small></div><button class="button small completion-reopen" data-reopen-task="'+esc(task.id)+'">Mark incomplete</button></div>').join('')+'</div></section>').join('')+'</div></div></article>').join('')+'</div>':'<div class="empty">Completed Huddle work will appear here by date.</div>')+'</section>'}
