function taskEngineMigration(){if(!state?.tasks)return 0;let changed=0;state.tasks=state.tasks.map(task=>{const sourceMap={EOD:'EOD',Huddle:'Morning Huddle',Today:"Today's Work",'End of Day':'EOD'};const source=sourceMap[task.source]||task.source||'Manual';const createdDate=task.createdDate||(task.createdAt||'').slice(0,10)||today();const next={...task,status:task.status==='done'?'done':task.status||'open',priority:task.priority||'medium',source,createdDate,committedDate:task.committedDate||task.movedToTodayDate||'',carryOverCount:Number(task.carryOverCount??task.carry??0),lastUpdated:task.lastUpdated||task.createdAt||new Date().toISOString(),history:Array.isArray(task.history)?task.history:[]};if(!next.history.length)next.history=[{at:next.createdAt||new Date().toISOString(),date:createdDate,event:'Created'}];if(next.status==='done'&&!next.history.some(event=>event.event==='Completed'))next.history=[...next.history,{at:next.completedAt||next.lastUpdated,date:next.completedDate||createdDate,event:'Completed'}];if(JSON.stringify(next)!==JSON.stringify(task))changed++;return next});return changed}
function taskIsOpen(task){return task.status!=='done'}
function taskMatchesToday(task){return taskIsOpen(task)&&(task.committedDate===today()||task.movedToTodayDate===today()||(!task.committedDate&&task.due&&task.due<=today()))}
function taskMatchesUpcoming(task){return taskIsOpen(task)&&task.due&&task.due>today()}
function taskMatchesOverdue(task){return taskIsOpen(task)&&task.due&&task.due<today()}
function taskMatchesFilters(task){return (todayWorkSource==='all'||task.source===todayWorkSource)&&(todayWorkPriority==='all'||(task.priority||'medium')===todayWorkPriority)}
function sortTodayTasks(items){return items.slice().sort((a,b)=>(a.due&&a.due<today()?0:1)-(b.due&&b.due<today()?0:1)||({high:0,medium:1,low:2}[a.priority]??1)-({high:0,medium:1,low:2}[b.priority]??1)||String(a.due||'').localeCompare(String(b.due||''))||String(a.title).localeCompare(String(b.title)))}
function todayWorkTabs(){return ['today','upcoming','overdue','completed','all'].map(tab=>`<button class="button small ${todayWorkTab===tab?'teal':''}" data-today-tab="${tab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}
function todayWorkFilterMarkup(){return `<div class="today-filters"><label>Source<select class="select" id="today-work-source"><option value="all" ${todayWorkSource==='all'?'selected':''}>All sources</option>${['EOD','Morning Huddle','Rock','IDS','L10','Manual'].map(source=>`<option value="${source}" ${todayWorkSource===source?'selected':''}>${source}</option>`).join('')}</select></label><label>Priority<select class="select" id="today-work-priority"><option value="all" ${todayWorkPriority==='all'?'selected':''}>All priorities</option><option value="high" ${todayWorkPriority==='high'?'selected':''}>High</option><option value="medium" ${todayWorkPriority==='medium'?'selected':''}>Medium</option><option value="low" ${todayWorkPriority==='low'?'selected':''}>Low</option></select></label></div>`}
function todayWorkItems(){let items;if(todayWorkTab==='today')items=state.tasks.filter(taskMatchesToday);else if(todayWorkTab==='upcoming')items=state.tasks.filter(taskMatchesUpcoming);else if(todayWorkTab==='overdue')items=state.tasks.filter(taskMatchesOverdue);else if(todayWorkTab==='completed')items=state.tasks.filter(task=>task.status==='done').sort((a,b)=>String(b.completedDate||b.completedAt||'').localeCompare(String(a.completedDate||a.completedAt||'')));else items=state.tasks.slice();return items.filter(taskMatchesFilters)}
function todayWorkGroupMarkup(items){if(todayWorkTab!=='upcoming')return items.length?items.map(taskRow).join(''):'<div class="empty">No work in this view.</div>';const groups=[['Tomorrow',task=>task.due===tomorrow()],['This Week',task=>task.due>tomorrow()&&task.due<=fridayOfWeek()],['Next Week',task=>task.due>fridayOfWeek()&&task.due<=addWeeks(fridayOfWeek(),1)],['Later',task=>task.due>addWeeks(fridayOfWeek(),1)]];return groups.map(([label,matches])=>{const group=items.filter(matches);return group.length?`<section class="carry-group"><div class="carry-group-heading"><h3>${label}</h3><span class="pill">${group.length}</span></div>${group.map(taskRow).join('')}</section>`:''}).join('')||'<div class="empty">No upcoming work.</div>'}
function unifiedTodayView(){taskEngineMigration();const items=todayWorkItems();return `<div class="hero"><div><div class="kicker">EXECUTE WITH INTENTION</div><h1>Today&#8217;s Work</h1><p>One execution view for work created across TalentisOS.</p></div><div class="today-actions"><button class="button teal today-add-button" data-add-today>+ Add Work</button></div></div><div class="card"><div class="today-work-tabs">${todayWorkTabs()}</div>${todayWorkTab==='all'?todayWorkFilterMarkup():''}<div class="card-head"><div><h2 class="section-title">${todayWorkTab[0].toUpperCase()+todayWorkTab.slice(1)} work</h2><span class="muted">${items.length} item${items.length===1?'':'s'} from the shared work engine</span></div></div><div class="task-list">${todayWorkGroupMarkup(todayWorkTab==='today'?sortTodayTasks(items):items)}</div></div>`}
document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-today-tab]'):null;if(!button)return;todayWorkTab=button.dataset.todayTab;render()},true);
document.addEventListener('change',event=>{if(event.target?.id==='today-work-source'){todayWorkSource=event.target.value;render()}if(event.target?.id==='today-work-priority'){todayWorkPriority=event.target.value;render()}},true);
let todayContext='home', performanceTab='overview';
function todayHomeView(){const open=state.tasks.filter(taskMatchesToday),overdue=state.tasks.filter(taskMatchesOverdue),exceptions=overdue.length+state.kpis.filter(k=>kpiStatus(k)!=='on-track').length;return `<div class="today-home"><div class="today-home-heading"><div><div class="kicker">TALENTISOS &#183; TODAY</div><h1>${new Date().toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long'})}</h1><p>${open.length} item${open.length===1?'':'s'} remaining${exceptions?' &#183; '+exceptions+' need attention':''}</p></div></div><div class="context-routines"><div class="context-routine"><div><strong>Morning Huddle</strong><span>${new Date().getHours()<11?'Ready to align the team':'Review priorities and commitments'}</span></div><button class="button small teal" data-context-view="huddle">${new Date().getHours()<11?'Start':'Open'}</button></div><div class="context-routine"><div><strong>End of Day</strong><span>Reflect &#183; Prepare &#183; Handover</span></div><button class="button small" data-context-view="eod">Start EOD</button></div></div>${exceptions?`<section class="needs-attention"><div class="section-kicker">NEEDS ATTENTION</div><h2 class="section-title">Keep the exceptions close</h2>${overdue.slice(0,3).map(task=>`<div class="status-row"><span>${esc(task.title)}</span><span class="status at-risk">Overdue</span></div>`).join('')}${state.kpis.filter(k=>kpiStatus(k)!=='on-track').slice(0,3).map(k=>`<div class="status-row"><span>${esc(k.name)}</span><span class="status ${kpiStatus(k)}">${kpiStatus(k)}</span></div>`).join('')}</section>`:''}<section class="today-home-work"><div class="section-kicker">TODAY’S WORK</div>${unifiedTodayView()}</section></div>`}
function performanceView(){const counts={total:state.kpis.length,on:state.kpis.filter(k=>kpiStatus(k)==='on-track').length,rocks:state.tasks.filter(t=>t.priority==='high'&&t.status!=='done').length};const detail=performanceTab==='scorecard'?scorecard():performanceTab==='rocks'?rocks():performanceTab==='management'?managementKpis():`<div class="performance-overview"><div class="hero"><div><div class="kicker">SEE THE TRUTH</div><h1>Performance</h1><p>${counts.on} of ${counts.total} KPIs on track · ${counts.rocks} active Rocks</p></div></div><section class="needs-attention">${state.kpis.filter(k=>kpiStatus(k)!=='on-track').map(k=>`<div class="status-row"><span>${esc(k.name)}</span><span class="status ${kpiStatus(k)}">${kpiStatus(k)}</span></div>`).join('')||'<div class="empty">Everything is on track.</div>'}</section></div>`;return `<div class="performance-shell"><div class="performance-tabs">${['overview','scorecard','rocks','management'].map(tab=>`<button class="button small ${performanceTab===tab?'teal':''}" data-performance-tab="${tab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div>${detail}</div>`}
document.addEventListener('click',event=>{const focus=event.target instanceof Element?event.target.closest('[data-today-focus]'):null;if(focus){todayContext='home';current='today';render();requestAnimationFrame(()=>document.querySelector('#today-work-section')?.scrollIntoView({behavior:'smooth',block:'start'}));return}const button=event.target instanceof Element?event.target.closest('[data-context-view]'):null;if(button){todayContext=button.dataset.contextView;current='today';render()}const tab=event.target instanceof Element?event.target.closest('[data-performance-tab]'):null;if(tab){performanceTab=tab.dataset.performanceTab;current='performance';render()}},true);
