render=()=>{let route=current;if(route==='tasks')route='today';if(route==='dashboard'||route==='huddle'||route==='eod'||route==='ids'){todayContext=route==='dashboard'?'home':route;route='today'}if(route==='rocks'||route==='scorecard'||route==='management-kpis'){performanceTab=route==='rocks'?'rocks':route==='scorecard'?'scorecard':'management';route='performance'}if(!['today','performance','l10','settings'].includes(route))route='today';current=route;layout();const view=route==='today'?todayContext==='home'?todayHomeView():todayContext==='huddle'?huddle():todayContext==='eod'?eod():todayContext==='ids'?ids():unifiedTodayView():route==='performance'?performanceView():({l10,settings}[route])();document.querySelector('#view').innerHTML=view;bind()};
todayView=()=>todayContext==='home'?todayHomeView():todayContext==='huddle'?huddle():todayContext==='eod'?eod():todayContext==='ids'?ids():unifiedTodayView();
todayHomeView=()=>{const open=state.tasks.filter(taskMatchesToday),overdue=state.tasks.filter(taskMatchesOverdue),exceptions=overdue.length+state.kpis.filter(k=>kpiStatus(k)!=='on-track').length,top3=state.eod.top3.split('\n').filter(Boolean);return `<div class="today-home today-inspired"><div class="today-inspired-top"><div class="today-inspired-brand">TALENTISOS <span>·</span> TODAY</div><div class="today-inspired-date">${new Date().toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</div></div><div class="today-inspired-hero"><div class="today-inspired-copy"><div class="kicker">LEADERSHIP RHYTHM</div><h1>Lead the day<br>before it leads<br>you.</h1><p>Your calm daily operating rhythm for priorities, risks, commitments and progress.</p></div><div class="today-inspired-actions"><button class="today-action-card today-action-primary" data-context-view="eod"><span class="today-action-icon">+</span><strong>Quick close</strong><small>END OF DAY</small></button><button class="today-action-card" data-today-focus="work"><span class="today-action-icon">&#8594;</span><strong>Today&#8217;s work</strong><small>${open.length} OPEN COMMITMENT${open.length===1?'':'S'}</small></button></div></div><div class="today-inspired-metrics"><div><span>Open commitments</span><strong>${open.length}</strong><small>${overdue.length} overdue</small></div><div><span>Top 3 ready</span><strong>${top3.length}</strong><small>Aligned from your EOD</small></div><div><span>KPI exceptions</span><strong>${state.kpis.filter(k=>kpiStatus(k)!=='on-track').length}</strong><small>Need attention this week</small></div><div><span>Rhythm this week</span><strong>${rhythmScore()}<em>/5</em></strong><small>Prepare &#8594; Improve</small></div></div>${exceptions?`<section class="needs-attention"><div class="section-kicker">NEEDS ATTENTION</div><h2 class="section-title">Keep the exceptions close</h2>${overdue.slice(0,3).map(task=>`<div class="status-row"><span>${esc(task.title)}</span><span class="status at-risk">Overdue</span></div>`).join('')}${state.kpis.filter(k=>kpiStatus(k)!=='on-track').slice(0,3).map(k=>`<div class="status-row"><span>${esc(k.name)}</span><span class="status ${kpiStatus(k)}">${kpiStatus(k)}</span></div>`).join('')}</section>`:''}<section id="today-work-section" class="today-home-work"><div class="section-kicker">TODAY’S WORK</div>${unifiedTodayView()}</section></div>`};
const inspiredHomeBase=todayHomeView;todayHomeView=()=>inspiredHomeBase().replace('<div class="today-inspired-metrics"><div><span>Open commitments','<div class="today-inspired-metrics"><button type="button" class="today-metric-tile" data-today-focus="work"><span>Open commitments').replace('</small></div><div><span>Top 3 ready','</small></button><button type="button" class="today-metric-tile" data-today-metric="huddle"><span>Top 3 ready').replace('</small></div><div><span>KPI exceptions','</small></button><button type="button" class="today-metric-tile" data-today-metric="performance"><span>KPI exceptions').replace('</small></div><div><span>Rhythm this week','</small></button><button type="button" class="today-metric-tile" data-today-metric="l10"><span>Rhythm this week').replace('</small></div></div>${exceptions?','</small></button></div></div>${exceptions?');
document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-today-metric]'):null;if(!button)return;button.classList.add('is-pressed');setTimeout(()=>button.classList.remove('is-pressed'),220);const metric=button.dataset.todayMetric;if(metric==='work'){todayContext='home';current='today';render();requestAnimationFrame(()=>document.querySelector('#today-work-section')?.scrollIntoView({behavior:'smooth',block:'start'}));return}if(metric==='performance')performanceTab='scorecard';setTimeout(()=>{todayContext=metric==='huddle'?'huddle':'home';current=metric==='performance'?'performance':metric==='l10'?'l10':'today';render()},90)},true);
