document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-print-today-work]'):null;if(!button)return;document.body.classList.add('printing-today-work');window.addEventListener('afterprint',()=>document.body.classList.remove('printing-today-work'),{once:true});window.print()},true);
const todayHomeWithUpdatedSubtitle=todayHomeView;todayHomeView=()=>todayHomeWithUpdatedSubtitle().replace('Your calm daily operating rhythm for priorities, risks, commitments and progress.','A simpler way to lead every workday.<br><br><strong>PREPARE &#8594; ALIGN &#8594; EXECUTE &#8594; REVIEW &#8594; IMPROVE</strong>');
