function meetingsHomeView(){return `<div class="hero"><div><div class="kicker">ALIGN &#8594; IMPROVE</div><h1>Meetings</h1><p>Bring the team rhythm, decisions and actions into one focused workspace.</p></div><button class="button teal" data-view="l10">Start L10 &#8594;</button></div><div class="bento"><button class="card span-4 contextual-link" data-view="l10"><div class="section-kicker">WEEKLY RHYTHM</div><h2 class="section-title">L10</h2><p class="muted">Run the team meeting and turn conversation into owned actions.</p></button><button class="card span-4 contextual-link" data-view="rocks"><div class="section-kicker">PRIORITIES</div><h2 class="section-title">Rocks</h2><p class="muted">Review the few commitments that move the team forward.</p></button><button class="card span-4 contextual-link" data-view="ids"><div class="section-kicker">DECISIONS</div><h2 class="section-title">IDS</h2><p class="muted">Identify, discuss and solve the issues blocking progress.</p></button></div>`}
function insightsHomeView(){const kpiExceptions=state.kpis.filter(k=>kpiStatus(k)!=='on-track'),overdue=state.tasks.filter(taskMatchesOverdue),exceptionCount=kpiExceptions.length+overdue.length;return `<div class="hero"><div><div class="kicker">SEE THE TRUTH</div><h1>Insights</h1><p>Exceptions, trends and evidence that help you decide what needs attention.</p></div><button class="button teal" data-view="scorecard">Open scorecard &#8594;</button></div><section class="insights-exceptions ${exceptionCount?'has-exceptions':''}"><div class="card-head"><div><div class="section-kicker">EXCEPTIONS FIRST</div><h2 class="section-title">${exceptionCount?'Needs attention':'Nothing needs your attention'}</h2></div><span class="pill">${exceptionCount} open</span></div>${exceptionCount?`${overdue.slice(0,4).map(task=>`<button class="status-row contextual-link" data-view="today"><span>${esc(task.title)}</span><span class="status at-risk">Overdue</span></button>`).join('')}${kpiExceptions.slice(0,4).map(k=>`<button class="status-row contextual-link" data-view="scorecard"><span>${esc(k.name)}</span><span class="status ${kpiStatus(k)}">${kpiStatus(k)}</span></button>`).join('')}`:'<p class="muted">Healthy KPIs and completed work stay quiet until they need review.</p>'}</section><div class="bento"><button class="card span-4 contextual-link" data-view="scorecard"><div class="section-kicker">MEASURE</div><h2 class="section-title">Scorecard</h2><p class="muted">See the weekly operating signals and focus on exceptions.</p></button><button class="card span-4 contextual-link" data-view="management-kpis"><div class="section-kicker">EVIDENCE</div><h2 class="section-title">Management KPIs</h2><p class="muted">Maintain targets, actuals and proof in one place.</p></button><button class="card span-4 contextual-link" data-view="rocks"><div class="section-kicker">PROGRESS</div><h2 class="section-title">Rock progress</h2><p class="muted">Review high-priority commitments against the team rhythm.</p></button></div>`}
// Canonical route boundary: compatibility renderers above remain available for legacy aliases,
