const accessibleInsightsHome=insightsHomeView;insightsHomeView=()=>accessibleInsightsHome().replace('<section class="insights-exceptions','<section aria-live="polite" class="insights-exceptions');
const accessibleTaskRow=taskRow;taskRow=task=>accessibleTaskRow(task).replace('aria-label="Complete task"',`aria-label="${task.status==='done'?'Mark task incomplete':'Complete task'}"`);
const conciseHuddle=huddle;huddle=()=>conciseHuddle().replace('Import from End of Day','Import outstanding work');
function routeFromHash(){const parts=location.hash.replace(/^#/,'').split('/').filter(Boolean),root=parts[0],mode=parts[1];if(root==='meetings'){todayContext='home';return'meetings'}if(root==='insights'){todayContext='home';return'insights'}if(root==='l10'){return'l10'}if(root==='settings'){return'settings'}if(root==='performance'||root==='scorecard'||root==='management-kpis'||root==='rocks'){performanceTab=root==='rocks'?'rocks':root==='scorecard'?'scorecard':root==='management-kpis'?'management':'overview';return'performance'}if(root==='dashboard'){todayContext='home';return'today'}if(root==='tasks'||root==='work'){todayContext='work';return'today'}if(root==='today'||root==='huddle'||root==='eod'||root==='ids'){todayContext=root==='today'?(mode||'home'):root;return'today'}return current}
function syncRouteHash(){const root=current==='meetings'?'meetings':current==='insights'?'insights':current==='performance'?performanceTab==='overview'?'insights':performanceTab:current==='today'?(todayContext==='home'?'today':todayContext==='work'?'today/work':`today/${todayContext}`):current;if(location.hash.slice(1)!==root)history.replaceState(null,'','#'+root)}
const renderWithDeepLinks=render;render=()=>{if(location.hash&&current==='dashboard')current=routeFromHash();syncRouteHash();renderWithDeepLinks()};window.addEventListener('hashchange',()=>{current=routeFromHash();render()});
